CREATE TABLE execution_plan(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,decision_id uuid NOT NULL,title text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','validating','awaiting_approval','approved','handed_off','running','exception','outcome_verification','completed','archived')),execution_owner_id uuid NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,tenant_id));
CREATE TABLE execution_plan_revision(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,plan_id uuid NOT NULL,revision_number integer NOT NULL CHECK(revision_number>0),objective text NOT NULL,conditions jsonb NOT NULL DEFAULT '[]',success_criteria jsonb NOT NULL DEFAULT '[]',risk_level text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','approved','superseded')),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,tenant_id),UNIQUE(plan_id,revision_number),FOREIGN KEY(plan_id,tenant_id) REFERENCES execution_plan(id,tenant_id) ON DELETE CASCADE);
CREATE TABLE work_package(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,revision_id uuid NOT NULL,title text NOT NULL,accountable_owner_id uuid NOT NULL,capability text NOT NULL,input_contract jsonb NOT NULL,output_contract jsonb NOT NULL,deadline_at timestamptz,completion_criteria jsonb NOT NULL DEFAULT '[]',status text NOT NULL DEFAULT 'pending',UNIQUE(id,tenant_id),FOREIGN KEY(revision_id,tenant_id) REFERENCES execution_plan_revision(id,tenant_id) ON DELETE CASCADE);
CREATE TABLE work_dependency(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,predecessor_id uuid NOT NULL,successor_id uuid NOT NULL,CHECK(predecessor_id<>successor_id),UNIQUE(id,tenant_id),UNIQUE(predecessor_id,successor_id),FOREIGN KEY(predecessor_id,tenant_id) REFERENCES work_package(id,tenant_id) ON DELETE CASCADE,FOREIGN KEY(successor_id,tenant_id) REFERENCES work_package(id,tenant_id) ON DELETE CASCADE);
CREATE TABLE execution_gate(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,plan_id uuid NOT NULL,gate_type text NOT NULL,required_authority text NOT NULL,condition jsonb NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','satisfied','rejected','expired')),requested_by uuid NOT NULL,UNIQUE(id,tenant_id),FOREIGN KEY(plan_id,tenant_id) REFERENCES execution_plan(id,tenant_id) ON DELETE CASCADE);
CREATE TABLE execution_approval(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,gate_id uuid NOT NULL,decision text NOT NULL CHECK(decision IN('approve','reject','revision_required')),rationale text NOT NULL,requested_by uuid NOT NULL,decided_by uuid NOT NULL,authorization_reference text NOT NULL,decided_at timestamptz NOT NULL DEFAULT now(),CHECK(requested_by<>decided_by),UNIQUE(id,tenant_id),FOREIGN KEY(gate_id,tenant_id) REFERENCES execution_gate(id,tenant_id) ON DELETE RESTRICT);
CREATE TABLE execution_handoff(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,plan_id uuid NOT NULL,destination text NOT NULL CHECK(destination IN('eng006_workflow','eng020_operations','eng021_dispatch','eng025_automation')),idempotency_key text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending',requested_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),external_reference text,UNIQUE(id,tenant_id),UNIQUE(tenant_id,destination,idempotency_key),FOREIGN KEY(plan_id,tenant_id) REFERENCES execution_plan(id,tenant_id) ON DELETE RESTRICT);
CREATE TABLE execution_status_reference(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,handoff_id uuid NOT NULL,source_system text NOT NULL,source_entity_id uuid NOT NULL,source_version text,status text NOT NULL,observed_at timestamptz NOT NULL,fresh_until timestamptz,UNIQUE(id,tenant_id),FOREIGN KEY(handoff_id,tenant_id) REFERENCES execution_handoff(id,tenant_id) ON DELETE CASCADE);
CREATE TABLE execution_exception(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,plan_id uuid NOT NULL,source text NOT NULL,category text NOT NULL,severity smallint NOT NULL CHECK(severity BETWEEN 1 AND 5),impact text NOT NULL,evidence jsonb NOT NULL DEFAULT '[]',owner_id uuid NOT NULL,status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,tenant_id),FOREIGN KEY(plan_id,tenant_id) REFERENCES execution_plan(id,tenant_id) ON DELETE CASCADE);
CREATE TABLE amendment_proposal(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,plan_id uuid NOT NULL,current_plan_hash text NOT NULL,trigger text NOT NULL,proposed_change jsonb NOT NULL,impact text,risk text,cost text,evidence jsonb NOT NULL DEFAULT '[]',status text NOT NULL DEFAULT 'pending',created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,tenant_id),FOREIGN KEY(plan_id,tenant_id) REFERENCES execution_plan(id,tenant_id) ON DELETE CASCADE);
CREATE TABLE resource_requirement(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,package_id uuid NOT NULL,resource_type text NOT NULL,quantity numeric CHECK(quantity>0),constraints jsonb NOT NULL DEFAULT '{}',UNIQUE(id,tenant_id),FOREIGN KEY(package_id,tenant_id) REFERENCES work_package(id,tenant_id) ON DELETE CASCADE);
CREATE TABLE execution_outcome(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,plan_id uuid NOT NULL,outcome jsonb NOT NULL,evidence jsonb NOT NULL DEFAULT '[]',verified_by uuid NOT NULL,verification_reference text NOT NULL,verified_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,tenant_id),UNIQUE(plan_id),FOREIGN KEY(plan_id,tenant_id) REFERENCES execution_plan(id,tenant_id) ON DELETE RESTRICT);
CREATE TABLE execution_audit_event(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,plan_id uuid NOT NULL,event_type text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',actor_id uuid,occurred_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,tenant_id),FOREIGN KEY(plan_id,tenant_id) REFERENCES execution_plan(id,tenant_id) ON DELETE CASCADE);
CREATE INDEX execution_plan_status_idx ON execution_plan(tenant_id,status,updated_at DESC);CREATE INDEX work_package_revision_idx ON work_package(tenant_id,revision_id,status);CREATE INDEX handoff_status_idx ON execution_handoff(tenant_id,destination,status);CREATE INDEX exception_status_idx ON execution_exception(tenant_id,plan_id,status);
CREATE OR REPLACE FUNCTION v09_immutable() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION '% is immutable',TG_TABLE_NAME; END $$ LANGUAGE plpgsql;
CREATE TRIGGER trg_approval_immutable BEFORE UPDATE OR DELETE ON execution_approval FOR EACH ROW EXECUTE FUNCTION v09_immutable();CREATE TRIGGER trg_outcome_immutable BEFORE UPDATE OR DELETE ON execution_outcome FOR EACH ROW EXECUTE FUNCTION v09_immutable();CREATE TRIGGER trg_audit_append_only BEFORE UPDATE OR DELETE ON execution_audit_event FOR EACH ROW EXECUTE FUNCTION v09_immutable();
CREATE OR REPLACE FUNCTION v09_no_cycle() RETURNS trigger AS $$ BEGIN IF EXISTS(WITH RECURSIVE s(id) AS(SELECT successor_id FROM work_dependency WHERE tenant_id=NEW.tenant_id AND predecessor_id=NEW.successor_id AND id<>NEW.id UNION SELECT d.successor_id FROM work_dependency d JOIN s ON d.predecessor_id=s.id WHERE d.tenant_id=NEW.tenant_id) SELECT 1 FROM s WHERE id=NEW.predecessor_id) THEN RAISE EXCEPTION 'Dependency cycle prohibited';END IF;RETURN NEW;END $$ LANGUAGE plpgsql;
CREATE TRIGGER trg_dependency_no_cycle BEFORE INSERT OR UPDATE ON work_dependency FOR EACH ROW EXECUTE FUNCTION v09_no_cycle();
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['execution_plan','execution_plan_revision','work_package','work_dependency','execution_gate','execution_approval','execution_handoff','execution_status_reference','execution_exception','amendment_proposal','resource_requirement','execution_outcome','execution_audit_event'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY %I ON %I FOR ALL USING (tenant_id=(auth.jwt()->>''tenant_id'')::uuid) WITH CHECK (tenant_id=(auth.jwt()->>''tenant_id'')::uuid)',t||'_tenant_policy',t);END LOOP;END $$;
